CREATE TABLE nexus.frecency (
    tenant_id      TEXT             NOT NULL,
    chunk_id       TEXT             NOT NULL,
    embedded_at    TIMESTAMPTZ      NOT NULL DEFAULT now(),
    ttl_days       INTEGER,
    frecency_score DOUBLE PRECISION NOT NULL DEFAULT 0,
    miss_count     INTEGER          NOT NULL DEFAULT 0,
    last_hit_at    TIMESTAMPTZ      NOT NULL DEFAULT now(),
    CONSTRAINT frecency_pk PRIMARY KEY (tenant_id, chunk_id),
    CONSTRAINT frecency_ttl_days_positive_chk CHECK (ttl_days IS NULL OR ttl_days > 0),
    CONSTRAINT frecency_chunk_id_canonical_check CHECK (chunk_id ~ '^[0-9a-f]{64}$')
);

CREATE INDEX idx_frecency_chunk    ON nexus.frecency (tenant_id, chunk_id);
CREATE INDEX idx_frecency_last_hit ON nexus.frecency (tenant_id, last_hit_at DESC);
CREATE INDEX idx_frecency_score    ON nexus.frecency (tenant_id, frecency_score DESC);

ALTER TABLE nexus.frecency ENABLE ROW LEVEL SECURITY;
ALTER TABLE nexus.frecency FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON nexus.frecency
    USING      (tenant_id = current_setting('nexus.tenant', true))
    WITH CHECK (tenant_id = current_setting('nexus.tenant', true));

COMMENT ON COLUMN nexus.frecency.chunk_id IS
  'No FK, by GRAIN, not by deferral (RDR-194 D7). nexus.chunks is keyed (tenant_id, collection, chash); frecency has no collection column -- its PK is (tenant_id, chunk_id), one row per chash per tenant ACROSS collections by design. Adding a collection column to make an FK expressible would change the table''s identity grain, a behaviour change, not hygiene. The standing detection for this edge is the nexus_diag debt view nexus.diag_chash_conformance (observe-only for this table; src/nexus/db/chash_tables.py). The engine-side ChashCensus leg this comment used to name was deleted at nexus-z0o2p.27 together with its only caller; D0.10''s one-for-one FK retirement does not fire here.';
